from fast_rub.utils import AntiSpam

antispam = AntiSpam(
    flood_max=5,
    flood_window=3.0,
    mute_duration=120.0,
)

@bot.on_message()
async def handler(msg: Message):
    is_spam, reason, violation = antispam.check(
        msg.chat_id, msg.sender_id, msg.text
    )

    if is_spam:
        await msg.reply(f"🚫 {reason}")
        await msg.delete()
    else:
        await msg.reply("✅ پیام شما پذیرفته شد.")
